class BaseAgentTool(object):
    """The base interface for a code-based agent tool"""

    def __init__(self):
        pass

    def get_descriptor(self, tool):
        """
        Returns the descriptor of the tool, as a dict containing:
           - description (str)
           - inputSchema (dict, a JSON Schema representation)
        """
        raise NotImplementedError(f"Required method: get_descriptor(self, tool). Please implement the get_descriptor method for the {type(self).__name__} tool.")


    def invoke(self, input, trace):
        """
        Invokes the tool.

        The arguments of the tool invocation are in input["input"], a dict
        """
        raise NotImplementedError(f"Required method: invoke(self, input, trace). Please implement the invoke method for the {type(self).__name__} tool.")


    def describe_tool_call(self, tool, descriptor, input):
        """
        Returns the description of a tool call as a string.

        Optional function.
        """
        pass  # Don't need to raise here, this method is optional


    def load_sample_query(self, tool):
        """
        Returns a sample query for the test panel in the Agent tool page.

        Optional function.

        The sample should be returned as a dict in the same format as input["input"]
        received in `invoke` function.
        """
        pass  # Don't need to raise here, this method is optional
